// Demo account storage is local to this browser/device (not a secure server account).
const PROFILE_STORE_KEY='gramsaarthi_profiles_v1';
function readProfiles(){try{return JSON.parse(localStorage.getItem(PROFILE_STORE_KEY)||'{}')||{};}catch(_){return {};}}
function persistCurrentProfile(){if(!state.user?.mobile)return;const profiles=readProfiles();profiles[state.user.mobile]={user:{...state.user},role:state.role,preferences:{...state.preferences},language:state.language};try{localStorage.setItem(PROFILE_STORE_KEY,JSON.stringify(profiles));}catch(_){toast('Could not save profile in this browser. Check browser storage settings.');}}
function restoreProfile(mobile){const record=readProfiles()[mobile];if(!record)return false;state.user={...record.user};state.role=record.role||record.user.role||'farmer';state.preferences={...state.preferences,...(record.preferences||{})};state.language=record.language||'en';return true;}
