function applyTheme(theme){state.preferences.theme=theme;document.documentElement.dataset.theme=theme;try{localStorage.setItem('gramsaarthi_theme',theme);}catch(_){}const dark=theme==='dark';const b=$('themeToggle');if(b){$('themeIcon').textContent=dark?'☀️':'🌙';$('themeLabel').textContent=dark?'Light':'Dark';b.setAttribute('aria-label',dark?'Switch to light theme':'Switch to dark theme');b.title=dark?'Switch to light theme':'Switch to dark theme';}}
function toggleTheme(){applyTheme(state.preferences.theme==='dark'?'light':'dark');toast(`${state.preferences.theme==='dark'?'Dark':'Light'} theme enabled.`);}
function setLanguage(lang){state.language=lang;try{localStorage.setItem('gramsaarthi_language',lang);}catch(_){}$('welcomeLanguage').value=lang;$('topLanguage').value=lang;document.documentElement.lang=lang;$('welcomeTitle').textContent=translations[lang].welcome;$('startBtn').textContent=translations[lang].continue;}
function showScreen(name){['welcomeScreen','loginScreen','appScreen'].forEach(id=>$(id).classList.toggle('hidden',id!==name));}
function toast(msg){$('toast').textContent=msg;$('toast').classList.remove('hidden');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').classList.add('hidden'),2600);}
function populateRoles(){
  const grid=$('roleCardGrid');
  if(!grid)return;
  grid.innerHTML=Object.entries(roles).map(([k,r])=>`<button type="button" class="role-card ${k===state.selectedRole?'selected':''}" data-register-role="${k}" aria-pressed="${k===state.selectedRole}"><span class="role-card-emoji">${r.emoji}</span><strong>${r.name}</strong><small>Personalized dashboard</small></button>`).join('');
  grid.querySelectorAll('[data-register-role]').forEach(btn=>btn.addEventListener('click',()=>{
    state.selectedRole=btn.dataset.registerRole;
    grid.querySelectorAll('[data-register-role]').forEach(card=>{
      const active=card.dataset.registerRole===state.selectedRole;
      card.classList.toggle('selected',active);
      card.setAttribute('aria-pressed',String(active));
    });
  }));
}
function startLogin(){showScreen('loginScreen');$('loginForm').classList.remove('hidden');$('otpForm').classList.add('hidden');$('registerForm').classList.add('hidden');$('authError').classList.add('hidden');}
function authError(msg){$('authError').textContent=msg;$('authError').classList.remove('hidden');}
function signIn(){const mobile=$('mobile').value.trim();if(!/^\d{10}$/.test(mobile)){authError('Please enter a valid 10-digit Indian mobile number.');return;}const profiles=readProfiles();if(profiles[mobile])$('otpHint').textContent='Demo OTP: 123456 · Saved profile found';else $('otpHint').textContent='Demo OTP: 123456 · First-time demo login';$('loginForm').classList.add('hidden');$('otpForm').classList.remove('hidden');$('authError').classList.add('hidden');toast('Demo OTP generated: 123456');}
function showRegister(){ $('loginForm').classList.add('hidden');$('otpForm').classList.add('hidden');$('registerForm').classList.remove('hidden');$('authError').classList.add('hidden');populateRoles();}
function register(){const name=$('fullName').value.trim(),mobile=$('regMobile').value.trim(),age=Number($('age').value),role=state.selectedRole;if(!name){authError('Please enter your name.');return;}if(!/^\d{10}$/.test(mobile)){authError('Please enter a valid 10-digit Indian mobile number.');return;}if(!age||age<13||age>110){authError('Please enter an age between 13 and 110.');return;}state.user={name,mobile,age,role};state.role=role;persistCurrentProfile();openDashboard();toast('Your demo profile has been saved in this browser.');}
function verifyOtp(){if($('otp').value.trim()!=='123456'){authError('Incorrect demo OTP. Please enter 123456.');return;}const mobile=$('mobile').value.trim();if(restoreProfile(mobile)){openDashboard();toast('Welcome back! Your saved profile has been restored.');return;}$('regMobile').value=mobile;$('loginForm').classList.add('hidden');$('otpForm').classList.add('hidden');$('registerForm').classList.remove('hidden');populateRoles();$('fullName').focus();toast('First login: complete your profile to save your account details.'); }
function showRolePicker(){openModal(`<div class="eyebrow">PERSONALIZE YOUR EXPERIENCE</div><h2>Which role describes you?</h2><p>Choose a role to see the most relevant tools, schemes and opportunities. You can change this later.</p><div class="grid grid-2">${Object.entries(roles).map(([k,r])=>`<button class="role-choice" data-role="${k}"><span>${r.emoji}</span><strong>${r.name}</strong><small>Personalized dashboard</small></button>`).join('')}</div>`);document.querySelectorAll('[data-role]').forEach(b=>b.addEventListener('click',()=>{state.role=b.dataset.role;state.user.role=state.role;closeModal();persistCurrentProfile();openDashboard();}));}
function openDashboard(){if(!state.user)state.user={name:'Demo User',mobile:'',age:30,role:state.role};persistCurrentProfile();$('topUser').innerHTML=`${escapeHtml(state.user.name)}<small>${roles[state.role].name}</small>`;$('profileBtn').querySelector('.avatar').textContent=roles[state.role].emoji;showScreen('appScreen');renderPage('dashboard');}
function escapeHtml(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function metricCard(m){return `<div class="card"><div class="card-head"><div class="metric-icon">${m[0]}</div><span class="tag">${m[3].includes('+')?'Trending':'Today'}</span></div><div class="metric">${m[2]}</div><div class="metric-label">${m[1]}</div><div class="metric-change" style="margin-top:8px;color:#738176">${m[3]}</div></div>`;}
function actionRows(items){return `<div class="list">${items.map((a,i)=>`<div class="list-row"><div class="list-icon">${a[0]}</div><div class="list-main"><strong>${a[1]}</strong><small>${a[2]}</small></div>${a[3]?`<span class="tag ${a[3]}">${a[3]==='red'?'Review':a[3]==='orange'?'Due soon':'Tip'}</span>`:`<button class="small-btn" data-action="${escapeHtml(a[1])}">View</button>`}</div>`).join('')}</div>`;}
function welcomeBanner(r){return `<div class="welcome-banner"><div><div class="eyebrow" style="color:#c9e7d0">YOUR PERSONAL WORKSPACE</div><h2>${r.emoji} Namaste, ${escapeHtml(state.user?.name||'friend')}!</h2><p>${r.greeting}<br>${r.subtitle}</p></div><div class="banner-emoji">${r.emoji}</div></div>`;}
function farmMap(){const ideal=state.farmView==='ideal',soil=state.farmView==='soil',health=state.farmView==='health';return `<div class="farm-map farm-view-${state.farmView}"><div class="plot plot1">${soil?'Moisture 62%':health?'Healthy · Wheat':'Wheat · Field 1'}</div><div class="plot plot2">${soil?'Moisture 31%':health?'Needs review · Mustard':'Mustard · Field 2'}</div><div class="plot plot3">${soil?'Moisture 18%':health?'Fallow · Plan crop':'Fallow · Field 3'}</div><div class="plot plot4">${soil?'Moisture 74%':health?'Healthy · Veg':'Vegetables · Field 4'}</div><div class="plot plot5">${ideal?'Rotation plan':soil?'Moisture 58%':health?'Monitor leaves':'Wheat · Field 5'}</div></div><div class="map-legend"><span style="--c:#5d9a4d">${ideal?'Planned crop':soil?'Good moisture':'Healthy crop'}</span><span style="--c:#c3a64d">${soil?'Moderate moisture':'Needs water'}</span><span style="--c:#d17b43">${ideal?'Rotation / rest':'Review field'}</span></div>`;}
function farmerExtra(){return `<div class="grid grid-2"><div class="card"><div class="card-head"><div><h3>My Farm · Field Explorer</h3><div class="card-sub">Choose a field layer to compare your plots</div></div><button class="link-btn" data-action="farm-report">Full report ↗</button></div><div class="farm-view-tabs"><button class="tab ${state.farmView==='current'?'active':''}" data-farmview="current">Current field</button><button class="tab ${state.farmView==='ideal'?'active':''}" data-farmview="ideal">Ideal plan</button><button class="tab ${state.farmView==='soil'?'active':''}" data-farmview="soil">Soil moisture</button><button class="tab ${state.farmView==='health'?'active':''}" data-farmview="health">Crop health</button></div>${farmMap()}<div class="section-title"><h2>Current vs. ideal farm</h2></div><div class="compare"><div class="compare-box"><strong>🗺️ Current layout</strong><small>Soil moisture varies across plots</small></div><div class="compare-box"><strong>✨ Ideal simulation</strong><small>Balanced water and crop planning</small></div></div><div class="impact-row"><div class="impact"><strong>₹1.25L</strong><small>Potential income*</small></div><div class="impact"><strong>−20%</strong><small>Water use*</small></div><div class="impact"><strong>−18%</strong><small>Fertilizer use*</small></div></div><p class="tiny-note">*Illustrative estimates for prototype demonstration, not a guaranteed forecast.</p></div><div class="card"><div class="card-head"><div><h3>Crop Advisor</h3><div class="card-sub">Seasonal guidance · sample recommendations</div></div><span class="tag">Kharif / Rabi</span></div><div class="tab-row"><button class="tab active" data-croptab="seasonal">Seasonal advice</button><button class="tab" data-croptab="pest">Pest & disease</button><button class="tab" data-croptab="irrigation">Irrigation</button></div><div id="cropAdvice"><div class="crop-cards"><div class="crop-card"><div class="crop-emoji">🫘</div><strong>Moong bean</strong><small>Low water demand</small></div><div class="crop-card"><div class="crop-emoji">🥜</div><strong>Groundnut</strong><small>Moderate investment</small></div><div class="crop-card"><div class="crop-emoji">🌾</div><strong>Sesame</strong><small>Check local suitability</small></div></div><div class="section-title"><h2>Sowing window</h2><span class="tag">Check local forecast</span></div><div class="list-row"><div class="list-icon">🗓️</div><div class="list-main"><strong>Moong bean</strong><small>Indicative window: 15 June – 30 June</small></div><button class="small-btn" data-action="sowing">Details</button></div><div class="section-title"><h2>Irrigation schedule</h2></div><div class="list-row"><div class="list-icon">💧</div><div class="list-main"><strong>Mustard Field 2</strong><small>Review soil moisture before watering</small></div><span class="tag orange">Tomorrow</span></div></div></div></div>`;}
function roleSpecific(role){if(role==='farmer')return farmerExtra();if(role==='fisher')return `<div class="grid grid-2"><div class="card"><div class="card-head"><div><h3>Pond health monitor</h3><div class="card-sub">Example readings — update with real sensors for live data</div></div><span class="tag">Sample data</span></div><div class="grid grid-3"><div class="impact"><strong>7.2</strong><small>pH level</small></div><div class="impact"><strong>28°C</strong><small>Temperature</small></div><div class="impact"><strong>6.8</strong><small>Dissolved oxygen*</small></div></div><div class="section-title"><h2>Fish growth status</h2></div><div class="list-row"><div class="list-icon">🐟</div><div class="list-main"><strong>Rohu · average weight 1.2 kg</strong><small>Estimated growth trend: +8% this cycle</small><div class="progress"><span style="width:70%"></span></div></div><span class="tag">Healthy</span></div><p class="tiny-note">*Illustrative values. Use calibrated pond tests and local fisheries guidance for real decisions.</p></div><div class="card"><h3>Today's pond tasks</h3>${actionRows(roleData.fisher.actions)}<div class="section-title"><h2>Feeding schedule</h2></div><div class="welcome-preview"><span class="preview-icon">🍽️</span><div><strong>Next feeding · 4:00 PM</strong><small>Adjust feed to fish biomass and water conditions.</small></div></div></div></div>`;
if(role==='student')return `<div class="grid grid-2"><div class="card"><div class="card-head"><h3>Learning progress</h3><span class="tag">Keep going</span></div>${[['Python Basics',60],['Digital Marketing',40],['Communication Skills',75]].map(x=>`<div class="list-row"><div class="list-icon">📘</div><div class="list-main"><strong>${x[0]}</strong><small>${x[1]}% complete</small><div class="progress"><span style="width:${x[1]}%"></span></div></div></div>`).join('')}</div><div class="card"><h3>Recommended courses & scholarships</h3>${actionRows([['💻','UI/UX Design Fundamentals','Beginner-friendly · sample course listing',''],['📊','Digital Marketing Basics','Build practical skills',''],['🎓','National Scholarship Portal','Verify eligibility and deadlines on the official portal','blue']])}<p class="tiny-note">Course listings are examples; provider, fee and scholarship availability must be verified.</p></div></div>`;
if(role==='entrepreneur')return `<div class="grid grid-2"><div class="card"><h3>Business performance</h3><div class="bar-row"><span>Revenue</span><div class="bar-track"><div class="bar-fill" style="width:88%"></div></div><b>₹1.25L</b></div><div class="bar-row"><span>Expenses</span><div class="bar-track"><div class="bar-fill" style="width:46%;background:#dca449"></div></div><b>₹65K</b></div><div class="bar-row"><span>Profit</span><div class="bar-track"><div class="bar-fill" style="width:42%;background:#548bb4"></div></div><b>₹60K</b></div><p class="tiny-note">Demo figures only. Add actual transactions for meaningful accounting.</p></div><div class="card"><h3>Top products</h3>${actionRows(roleData.entrepreneur.actions)}<button class="btn btn-outline btn-full" data-action="business-report">View business report</button></div></div>`;
if(role==='artisan')return `<div class="grid grid-2"><div class="card"><div class="card-head"><h3>My products</h3><button class="small-btn" data-action="add-product">+ Add product</button></div><div class="crop-cards">${[['🏺','Painted pottery','₹850'],['📿','Handmade jewellery','₹1,250'],['🪵','Wood décor','₹950']].map(p=>`<div class="crop-card"><div class="crop-emoji">${p[0]}</div><strong>${p[1]}</strong><small>${p[2]} · sample price</small></div>`).join('')}</div></div><div class="card"><h3>Order management</h3>${actionRows([['🧾','New order #GS104','2 items · Confirm delivery','orange'],['📦','Order #GS102','Ready to dispatch',''],['⭐','Customer review','A new review is waiting','blue']])}</div></div>`;
if(role==='labour')return `<div class="grid grid-2"><div class="card"><div class="card-head"><h3>Nearby jobs</h3><button class="link-btn" data-action="all-jobs">View all jobs ↗</button></div>${actionRows(roleData.labour.actions)}<p class="tiny-note">Wages and distance are example listings. Confirm job details directly with the employer.</p></div><div class="card"><h3>Work and scheme status</h3><div class="impact-row"><div class="impact"><strong>12/100</strong><small>Work days tracked*</small></div><div class="impact"><strong>₹2,160</strong><small>Demo earnings*</small></div><div class="impact"><strong>4</strong><small>Support options</small></div></div><div class="section-title"><h2>Next steps</h2></div>${actionRows([['🪪','Review job card details','Ask your Gram Panchayat for official status',''],['📄','Check rural employment support','Confirm local process and eligibility','blue']])}</div></div>`;
if(role==='livestock')return `<div class="grid grid-2"><div class="card"><h3>Animal overview</h3><div class="crop-cards"><div class="crop-card"><div class="crop-emoji">🐄</div><strong>Cows · 4</strong><small>3 healthy · 1 monitor</small></div><div class="crop-card"><div class="crop-emoji">🐐</div><strong>Goats · 3</strong><small>Routine care</small></div><div class="crop-card"><div class="crop-emoji">🐔</div><strong>Poultry · 12</strong><small>Feed check today</small></div></div><div class="section-title"><h2>Milk production</h2></div><div class="metric">42.5 L <span class="metric-change">+6% this week</span></div><div class="progress"><span style="width:72%"></span></div></div><div class="card"><h3>Today's animal care tasks</h3>${actionRows(roleData.livestock.actions)}<p class="tiny-note">Health reminders are informational and do not replace veterinary advice.</p></div></div>`;
return `<div class="grid grid-2"><div class="card"><h3>Business ideas for you</h3>${actionRows(roleData.women.actions)}<button class="btn btn-outline btn-full" data-action="business-ideas">Explore all ideas</button></div><div class="card"><h3>Skills and market</h3><div class="welcome-preview"><span class="preview-icon">🎓</span><div><strong>Food processing course</strong><small>60% complete · practice the next module</small><div class="progress"><span style="width:60%"></span></div></div></div>${actionRows([['🛍️','Local weekly market','Explore products and customer demand',''],['🤝','Self-help group resources','Find local training and support','blue']])}</div></div>`;}
function sharedContent(){return `<div class="grid grid-3"><div class="card"><div class="card-head"><div class="metric-icon">🏛️</div><span class="tag">Role matched</span></div><h3>Government schemes</h3><p class="card-sub">Explore support you may be eligible for.</p><div class="metric" style="font-size:20px">8 options</div><button class="link-btn" data-page="schemes">Explore schemes →</button></div><div class="card"><div class="card-head"><div class="metric-icon">📊</div><span class="tag">Sample values</span></div><h3>Market prices</h3><p class="card-sub">Indicative mandi prices for demonstration.</p><div class="metric" style="font-size:20px">5 crops</div><button class="link-btn" data-page="market">View market →</button></div><div class="card"><div class="card-head"><div class="metric-icon">📍</div><span class="tag">Explore</span></div><h3>Nearby services</h3><p class="card-sub">Find local support, health and agriculture services.</p><div class="metric" style="font-size:20px">4 services</div><button class="link-btn" data-page="services">Find services →</button></div></div>`;}
function renderDashboard(){const r=roles[state.role],d=roleData[state.role];$('pageEyebrow').textContent='YOUR PERSONAL WORKSPACE';$('pageTitle').textContent=r.greeting;$('pageSubtitle').textContent=r.subtitle;$('pageContent').innerHTML=welcomeBanner(r)+`<div class="grid grid-4">${d.metrics.map(metricCard).join('')}</div><div class="section-title"><div><h2>${state.role==='farmer'?'Farm overview':state.role==='fisher'?'Pond overview':state.role==='student'?'Your learning journey':state.role==='labour'?'Jobs that may suit you':state.role==='women'?'Business ideas for you':state.role==='livestock'?'Animal overview':state.role==='artisan'?'Products & orders':'Business overview'}</h2><p>Personalized information for your selected role.</p></div><button class="link-btn" data-page="opportunities">Explore opportunities →</button></div>${roleSpecific(state.role)}<div class="section-title"><div><h2>Useful for you</h2><p>Shared rural services and updates.</p></div><button class="link-btn" data-page="schemes">All services →</button></div>${sharedContent()}<div class="grid grid-2" style="margin-top:16px"><div class="card"><div class="card-head"><div><h3>Recommended actions</h3><div class="card-sub">Suggested based on your role</div></div><span class="tag orange">Today</span></div>${actionRows(d.actions)}</div><div class="card"><div class="card-head"><div><h3>Smart alerts</h3><div class="card-sub">Reminders and community updates</div></div><span class="tag red">3 new</span></div>${actionRows([['🌦️','Weather update','Check local forecast before outdoor work','blue'],['📣','New local opportunity','A role-matched update is available',''],['🔔','Reminder','Review your upcoming tasks','orange']])}</div></div>`;}
function renderSchemes(){ $('pageEyebrow').textContent='SUPPORT & SERVICES';$('pageTitle').textContent='Government schemes';$('pageSubtitle').textContent='Explore support programmes and verify eligibility through official sources.';$('pageContent').innerHTML=`<div class="welcome-banner"><div><h2>Find support that fits your needs</h2><p>Browse examples by area. Scheme details, eligibility and deadlines can change — always confirm through official portals.</p></div><div class="banner-emoji">🏛️</div></div><div class="tab-row">${['All','Farmers','Livestock','Women & Business','Students','Skills & Jobs','Fisheries','Jobs'].map(x=>`<button class="tab ${state.schemeFilter===x?'active':''}" data-schemefilter="${x}">${x}</button>`).join('')}</div><div class="grid grid-3">${schemes.map((s,i)=>({s,i})).filter(x=>state.schemeFilter==='All'||x.s.type===state.schemeFilter).map(({s,i})=>`<div class="scheme-card"><div class="scheme-icon">${s.icon}</div><span class="tag">${s.type}</span><strong>${s.name}</strong><p>${s.desc}</p><button class="small-btn" data-scheme="${i}">View details</button></div>`).join('')}</div><p class="tiny-note">Gramsaarthi prototype does not submit applications or determine official eligibility. Verify information with the relevant government department.</p>`;}
function renderMarket(){ $('pageEyebrow').textContent='LOCAL ECONOMY';$('pageTitle').textContent='Market prices';$('pageSubtitle').textContent='Example prices for the prototype — not a live mandi feed.';$('pageContent').innerHTML=`<div class="welcome-banner"><div><h2>Make more informed market decisions</h2><p>Compare indicative crop prices and plan what to check at your local mandi.</p></div><div class="banner-emoji">📈</div></div><div class="grid grid-3"><div class="card"><div class="metric">5</div><div class="metric-label">Crops shown</div></div><div class="card"><div class="metric">Bhopal</div><div class="metric-label">Example market region</div></div><div class="card"><div class="metric">Today</div><div class="metric-label">Demo snapshot label</div></div></div><div class="card" style="margin-top:16px"><div class="market-table-heading"><div><h3>Mandi prices (demo data)</h3><div class="card-sub">Prices in Indian rupees per quintal</div></div><div class="market-filter-chips" aria-label="Filter market prices"><button class="chip active" data-marketfilter="All">All crops</button><button class="chip" data-marketfilter="Up">Prices rising</button><button class="chip" data-marketfilter="Down">Prices falling</button></div></div><div class="table-wrap"><table><thead><tr><th>Crop</th><th>Market</th><th>Indicative price</th><th>Change</th><th>Action</th></tr></thead><tbody id="marketRows">${marketRows(marketData)}</tbody></table></div></div>`;}
function marketRows(data){return data.map(m=>`<tr><td><strong>${m.icon} ${m.crop}</strong></td><td>${m.market}</td><td><strong>${m.price}</strong> / ${m.unit}</td><td style="color:${m.up?'#168353':'#b44b3f'};font-weight:800">${m.change}</td><td><button class="small-btn" data-action="price-${m.crop}">Details</button></td></tr>`).join('');}
function renderCommunity(){ $('pageEyebrow').textContent='YOUR COMMUNITY';$('pageTitle').textContent='Community feed';$('pageSubtitle').textContent='Share experiences, learn from neighbours and discover local updates.';$('pageContent').innerHTML=`<div class="grid grid-2"><div><div class="card"><div class="post-compose-head"><h3>Share an update</h3><textarea id="postText" class="field" placeholder="Write a tip, question or update…"></textarea></div><div style="display:flex;justify-content:space-between;align-items:center;margin-top:10px"><span class="tiny-note">Be kind. Do not share private information.</span><button class="btn btn-primary" id="publishPost">Publish demo post</button></div></div><div id="feedPosts" style="margin-top:14px">${feedPost('Ramesh Yadav','Farmer · Maharashtra','Sharing water-saving irrigation tips helped me plan the week. Has anyone tried mulching for vegetables?','🌱',128)}${feedPost('Sushma Bai','Rural entrepreneur','Our self-help group is exploring homemade food products. Looking for packaging ideas and local training.','🧺',84)}${feedPost('Anita Patel','Student','I am comparing beginner computer courses. Please share free learning resources you found useful!','📚',52)}</div></div><div class="card"><h3>Community guidelines</h3>${actionRows([['🤝','Respect everyone','No harassment or discriminatory content',''],['🔎','Check information','Verify scheme and health claims before sharing',''],['🔒','Protect privacy','Never post OTPs, bank details or private documents','red']])}<div class="section-title"><h2>Trending topics</h2></div><div class="tab-row"><button class="tab active">#WaterSaving</button><button class="tab">#RuralJobs</button><button class="tab">#SkillIndia</button><button class="tab">#MarketTips</button></div></div></div>`;}
function feedPost(name,role,text,emoji,likes){return `<div class="feed-post"><div class="post-head"><div class="post-avatar">${emoji}</div><div><strong>${name}</strong><small>${role} · 2 hours ago</small></div><span style="margin-left:auto;color:#8a978e">•••</span></div><p>${text}</p><div class="post-actions"><button data-like>♡ ${likes} Likes</button><button data-action="comment">◯ Comment</button><button data-action="share">↗ Share</button></div></div>`;}
function renderServices(){ $('pageEyebrow').textContent='LOCAL SUPPORT';$('pageTitle').textContent='Nearby services';$('pageSubtitle').textContent='Illustrative service directory. Location and distances are demo placeholders.';$('pageContent').innerHTML=`<div class="grid grid-2"><div class="card"><div class="card-head"><div><h3>Services around your community</h3><div class="card-sub">Sample map view · not GPS-based</div></div><span class="tag">Demo map</span></div><div class="service-map-viewport" id="mapViewport"><div class="service-map" id="demoMap" tabindex="0" aria-label="Movable demo village map"><div class="map-road road-a"></div><div class="map-road road-b"></div><div class="map-water"></div><div class="map-pin" data-place="Primary Health Centre · 3.2 km" style="left:20%;top:30%"><span>🏥</span><b>Health Centre</b></div><div class="map-pin" data-place="Krishi Vigyan Kendra · 4.2 km" style="left:57%;top:20%"><span>🌾</span><b>Krishi Kendra</b></div><div class="map-pin" data-place="Gram Panchayat Office · 1.8 km" style="left:68%;top:61%"><span>🏛️</span><b>Panchayat</b></div><div class="map-pin" data-place="Skill Training Centre · 4.7 km" style="left:35%;top:67%"><span>🧰</span><b>Skill Centre</b></div><div class="map-pin" data-place="Village Market · 2.1 km" style="left:82%;top:38%"><span>🛒</span><b>Village Market</b></div><div class="map-label">DEMO VILLAGE · Drag to move · Click a pin for details</div></div></div><div class="map-controls"><button class="small-btn" id="mapReset">Reset map</button><span id="mapPlaceInfo" class="tiny-note">Click any labelled place to see its sample details.</span></div><p class="tiny-note">Enable a verified location service and real directory data for accurate nearby results.</p></div><div class="card"><div class="card-head"><h3>Service directory</h3><select class="field" id="serviceFilter" style="width:130px;padding:8px;min-height:36px"><option>All services</option><option>Health</option><option>Agriculture</option><option>Government</option><option>Skills</option></select></div><div id="serviceRows">${serviceRows('All services')}</div></div></div>`;}
const services=[['🏥','Primary Health Centre','Health','3.2 km away','Health services and general enquiries'],['🌱','Krishi Vigyan Kendra','Agriculture','4.2 km away','Agriculture training and crop guidance'],['🏛️','Gram Panchayat Office','Government','1.8 km away','Local certificates and scheme guidance'],['🧰','Skill Training Centre','Skills','4.7 km away','Ask about current training batches']];
function serviceRows(filter){return `<div class="list">${services.filter(s=>filter==='All services'||s[2]===filter).map(s=>`<div class="list-row"><div class="list-icon">${s[0]}</div><div class="list-main"><strong>${s[1]}</strong><small>${s[4]}</small></div><div class="list-end">${s[3]}<br><button class="link-btn" data-action="service-${s[1]}">Details</button></div></div>`).join('')}</div>`;}
function renderOpportunities(){ $('pageEyebrow').textContent='NEXT STEPS';$('pageTitle').textContent='Opportunities for you';$('pageSubtitle').textContent='Explore practical next steps matched to your selected role.';const r=roles[state.role];let cards=[];if(state.role==='student')cards=[['📚','Free beginner courses','Learn digital skills, Python and communication.','Explore learning'],['🎓','Scholarships','Review education support and deadlines.','Check eligibility'],['🧑‍💻','Career starter paths','Build a small portfolio and practice skills.','Make a plan']];else if(state.role==='farmer')cards=[['🌱','Crop planning','Compare crop options with local conditions.','Explore crops'],['💧','Water management','Review irrigation and soil moisture practices.','View advice'],['🏛️','Farm support schemes','Verify insurance and farmer support options.','Browse schemes']];else if(state.role==='labour')cards=[['🧰','Nearby work','Review example job listings and wage details.','Find jobs'],['📄','Work documentation','Check what documents your local office requires.','View checklist'],['🎓','Skill training','Explore training that may widen job options.','Find training']];else if(state.role==='fisher')cards=[['🐟','Pond management','Review water testing and feeding routines.','View checklist'],['🏛️','Fisheries support','Check your state fisheries department.','Browse schemes'],['📈','Market planning','Track harvest costs and selling prices.','Plan harvest']];else if(state.role==='livestock')cards=[['🐄','Animal care','Review routine care and veterinary reminders.','View tasks'],['🌾','Feed planning','Track feed stock and daily usage.','Plan feed'],['🏛️','Livestock support','Explore training and approved support options.','Browse schemes']];else if(state.role==='artisan')cards=[['🛍️','Product showcase','Prepare photos and descriptions for your products.','Manage products'],['📦','Order management','Track deadlines and fulfilment.','View orders'],['📣','Find customers','Explore community and local market channels.','Explore markets']];else if(state.role==='entrepreneur')cards=[['📊','Business finance','Record income, expenses and cash flow.','View finance'],['🛍️','Product growth','Identify popular products and customer feedback.','View products'],['🤝','Business support','Explore training, SHGs and official support.','Browse schemes']];else cards=[['🧺','Small business ideas','Explore low-investment options and training.','Explore ideas'],['🎓','Skill development','Find courses that suit your schedule.','Find courses'],['🛍️','Local markets','Learn about customers and selling channels.','Explore markets']];$('pageContent').innerHTML=`<div class="welcome-banner"><div><h2>${r.emoji} Opportunities matched to ${r.name.toLowerCase()}s</h2><p>These are suggested starting points. Confirm costs, eligibility, deadlines and local availability before acting.</p></div><div class="banner-emoji">✧</div></div><div class="grid grid-3">${cards.map((c,i)=>`<div class="card"><div class="metric-icon">${c[0]}</div><h3 style="margin-top:15px">${c[1]}</h3><p class="card-sub" style="line-height:1.7;min-height:40px">${c[2]}</p><button class="btn btn-outline btn-full" data-opportunity="${i}">${c[3]} →</button></div>`).join('')}</div><div class="section-title"><div><h2>Suggested next steps</h2><p>Simple actions to get started.</p></div></div><div class="card">${actionRows([['✓','Complete your profile','Add your preferred district and interests',''],['🔔','Review alerts','Check reminders relevant to your role',''],['🏛️','Verify official information','Use the relevant government department website','blue']])}</div>`;}
function renderProfile(){
 $('pageEyebrow').textContent='YOUR ACCOUNT';$('pageTitle').textContent='My profile';$('pageSubtitle').textContent='Edit your details, role and preferences. Changes update your Gramsaarthi workspace.';
 const u=state.user||{name:'Demo User',mobile:'',age:30,role:state.role};
 $('pageContent').innerHTML=`<div class="grid grid-2"><div class="card profile-card"><div class="profile-card-head"><div class="profile-avatar-large">${roles[state.role].emoji}</div><div><h2>${escapeHtml(u.name||'Demo User')}</h2><p>${roles[state.role].name}</p><span class="tag">Demo profile</span></div></div><form id="profileForm" class="profile-form"><label class="field-label" for="profileName">Full name</label><input class="field" id="profileName" required maxlength="80" value="${escapeHtml(u.name||'')}" placeholder="Your full name"><label class="field-label" for="profileMobile">Mobile number</label><input class="field" id="profileMobile" inputmode="numeric" maxlength="10" value="${escapeHtml(u.mobile||'')}" placeholder="10-digit mobile number"><label class="field-label" for="profileAge">Age</label><input class="field" id="profileAge" type="number" min="13" max="110" value="${Number(u.age)||''}" required><label class="field-label" for="profileRole">Your role</label><select class="field" id="profileRole">${Object.entries(roles).map(([k,r])=>`<option value="${k}" ${state.role===k?'selected':''}>${r.emoji} ${r.name}</option>`).join('')}</select><label class="field-label" for="profileDistrict">District / preferred location</label><input class="field" id="profileDistrict" value="${escapeHtml(state.preferences.district||'')}" placeholder="e.g. Bhopal"><label class="field-label" for="profileInterests">Interests and preferences</label><textarea class="field" id="profileInterests" rows="3" placeholder="Schemes, jobs, training, crop advice…">${escapeHtml(state.preferences.interests||'')}</textarea><label class="check-row"><input id="profileNotifications" type="checkbox" ${state.preferences.notifications?'checked':''}> Receive demo reminders and role-based alerts</label><button class="btn btn-primary btn-full" type="submit">Save profile changes</button></form></div><div class="card"><h3>Personalized for your role</h3><p class="card-sub">Your role changes the dashboard and recommendations you see.</p><div class="profile-role-summary"><div class="metric-icon">${roles[state.role].emoji}</div><div><strong>${roles[state.role].name}</strong><p>${roles[state.role].subtitle}</p></div></div><div class="list">${[['🏛️','Government schemes','Browse support programmes relevant to your needs.','schemes'],['✨','Opportunities','See suggestions based on your role.','opportunities'],['📍','Nearby services','Explore sample community services on the demo map.','services']].map(x=>`<button class="profile-shortcut" data-page="${x[3]}"><span>${x[0]}</span><span><strong>${x[1]}</strong><small>${x[2]}</small></span><b>→</b></button>`).join('')}</div><div class="welcome-preview"><span class="preview-icon">🔐</span><div><strong>Your information stays in this demo session</strong><small>This prototype does not send your details to a server. Refreshing the page may reset the session.</small></div></div></div></div>`;
 $('profileForm').onsubmit=e=>{e.preventDefault();const name=$('profileName').value.trim(),mobile=$('profileMobile').value.trim(),age=Number($('profileAge').value),role=$('profileRole').value;if(!name){toast('Please enter your name.');return;}if(mobile&&!/^\d{10}$/.test(mobile)){toast('Enter a valid 10-digit mobile number.');return;}if(!age||age<13||age>110){toast('Enter an age between 13 and 110.');return;}state.user={...state.user,name,mobile,age,role};state.role=role;state.preferences.district=$('profileDistrict').value.trim();state.preferences.interests=$('profileInterests').value.trim();state.preferences.notifications=$('profileNotifications').checked;persistCurrentProfile();openDashboard();toast('Profile saved on this device. Your dashboard is personalized.');};
}
function renderPage(page){state.page=page;document.querySelectorAll('[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===page));if(page==='dashboard')renderDashboard();else if(page==='schemes')renderSchemes();else if(page==='market')renderMarket();else if(page==='community')renderCommunity();else if(page==='services')renderServices();else if(page==='profile')renderProfile();else renderOpportunities();}
function openModal(html){$('modalBody').innerHTML=html;$('modalOverlay').classList.remove('hidden');}
function closeModal(){$('modalOverlay').classList.add('hidden');}
function showScheme(index){const s=schemes[index];if(!s)return;openModal(`<div class="eyebrow">${s.type}</div><h2>${s.icon} ${s.name}</h2><p>${s.detail}</p><div class="welcome-preview"><span class="preview-icon">🔎</span><div><strong>Before applying</strong><small>Confirm current guidelines, eligibility, documents and dates through the official government source.</small></div></div><button class="btn btn-primary btn-full" id="schemeConfirm">I understand</button>`);$('schemeConfirm').onclick=()=>{closeModal();toast('Please verify current details with the official department.');};}
function actionDetail(action){const text={
'farm-report':'Your farm report combines field conditions, crop planning and resource estimates. This prototype uses illustrative plots and sample values; connect real farm boundaries, weather and soil data before relying on recommendations.',
'sowing':'Sowing windows depend on region, variety, soil moisture and forecast. Treat the displayed dates as examples and consult local agriculture extension guidance.',
'business-report':'Business report includes revenue, expenses, profit and product performance. The figures shown are sample values; record actual transactions before using this for decisions.',
'add-product':'Product creation demo: prepare a clear product name, description, price, stock count and photo. A real version needs secure database storage and image uploads.',
'all-jobs':'Job listings in this prototype are examples. A production version should verify employers, wages, work location, safety requirements and contact details.',
'business-ideas':'Explore options such as food processing, tailoring, crafts and local services. Compare startup costs, training, market demand and safety requirements first.',
'comment':'Comments are a prototype interaction. A production community feature needs moderation, abuse reporting and privacy controls.',
'share':'Share feature preview: a production app could create a safe link to this public post.',
'service':'This service is a sample listing; exact address, opening hours and distance have not been verified.'
};const key=action.startsWith('price-')?'price':action.startsWith('service-')?'service':action;let body=text[key]||`This ${action} feature is represented in the prototype. It can be connected to verified local data and a secure backend in a production build.`;if(key==='price'){const crop=action.slice(6),m=marketData.find(x=>x.crop===crop);body=`${crop}: ${m?.price||'Sample price'} per quintal at ${m?.market||'example market'}. This is illustrative demo data, not a live or guaranteed market quote. Confirm the current price directly with the mandi.`;}openModal(`<div class="eyebrow">GRAMSAARTHI TOOL</div><h2>${escapeHtml(action.replace(/-/g,' ').replace(/\b\w/g,c=>c.toUpperCase()))}</h2><p>${body}</p><button class="btn btn-primary btn-full" id="detailOk">Got it</button>`);$('detailOk').onclick=closeModal;}
function assistantAnswer(q){const s=q.toLowerCase(),role=state.role;let answer;
if(/hello|hi\b|namaste|hey/.test(s)) answer=`Namaste ${state.user?.name||'friend'}! I am here to help. You are using the ${roles[role].name} workspace. Ask me about your dashboard, schemes, services or opportunities.`;
else if(/scheme|government|subsidy|benefit|yojana|पेंशन|योजना/.test(s)) answer=`For ${roles[role].name.toLowerCase()} users, start with Government Schemes and filter by your area of interest. Check eligibility, documents and deadlines with the official department or Gram Panchayat before applying. I cannot verify live eligibility in this demo.`;
else if(/job|work|wage|labour|काम|नौकरी/.test(s)) answer=role==='labour'?`Your Landless Labourer dashboard lists example jobs and daily wages. Open Opportunities for job-search tips. Verify the employer, worksite, wage, hours and safety conditions before accepting any job.`:`Open Opportunities to explore role-relevant work and livelihood ideas. Job availability shown here is sample content, so confirm vacancies and terms locally.`;
else if(/crop|farm|soil|irrigat|rain|weather|seed|fertili|pest|disease|फसल|खेती/.test(s)) answer=`For farm decisions, compare crop season, soil type, water availability and local forecast. The farmer dashboard has a simulated field map and seasonal, pest and irrigation tabs. Its numbers are examples, not live sensor or weather readings; confirm with your local Krishi Vigyan Kendra.`;
else if(/fish|pond|ph level|oxygen|feeding|मछली/.test(s)) answer=`For fisheries, your dashboard shows sample pH, temperature, growth and feeding information. Test pond water with appropriate kits and follow local fisheries guidance; the readings here are not connected to sensors.`;
else if(/animal|cow|cattle|milk|livestock|vaccin|पशु|दूध/.test(s)) answer=`Your Livestock Rearer dashboard includes example animal counts, milk production and care reminders. Keep vaccination and treatment records and consult a qualified veterinary professional for illness or medication decisions.`;
else if(/business|profit|revenue|expense|product|sales|order|craft|artisan|महिला|income|कमाई/.test(s)) answer=`Your ${roles[role].name} workspace includes business ideas, product or order tracking and sample income/expense figures. Use the relevant dashboard tools to plan, and replace sample numbers with your actual records before making financial decisions.`;
else if(/student|course|scholar|learn|certificate|college|study|पढ़ाई/.test(s)) answer=`Open Opportunities and your dashboard for example beginner courses, skill paths and scholarship reminders. Check the course provider, fees, certificate rules and scholarship deadlines on the official platform before enrolling.`;
else if(/market|mandi|price|wheat|paddy|soybean|बाजार|भाव/.test(s)) answer=`Open Market Prices and search by crop or mandi. The displayed prices are demo values, not live market quotes. Confirm current rates with your local mandi or an official market information source.`;
else if(/nearby|service|hospital|clinic|panchayat|location|map|नजदीक/.test(s)) answer=`Open Nearby Services and drag the demo map to explore labelled sample places. Click a map pin for details. Locations and distances are placeholders and are not GPS-verified.`;
else if(/profile|age|name|role|preference|edit/.test(s)) answer=`Click My profile in the Workspace menu. You can edit your name, mobile number, age, role, preferred district, interests and reminder preference, then save to refresh your personalized dashboard.`;
else if(/help|what can you do|features/.test(s)) answer=`I can guide you around Gramsaarthi: government schemes, mandi prices, community feed, nearby services, opportunities, and role-specific tools for farmers, rural women, labourers, livestock rearers, entrepreneurs, artisans, fishers and students. Tell me what you want to do and I will suggest the relevant section.`;
else answer=`I understood your question as: “${q}”. I can offer general guidance and help you navigate the ${roles[role].name} dashboard, but this offline prototype has no live AI service or access to current government, market or personal records. Try asking about schemes, jobs, crops, pond health, animal care, business, courses, market prices, nearby services or editing your profile.`;
return answer;}
function appendAssistantMessage(question,answer){const chat=$('assistantChat');chat.insertAdjacentHTML('beforeend',`<div class="assistant-user-bubble">${escapeHtml(question)}</div><div class="assistant-reply">${escapeHtml(answer)}</div>`);chat.scrollTop=chat.scrollHeight;}

function openAssistant(){$('assistantPanel').classList.remove('hidden');}
function bindEvents(){
$('startBtn').onclick=startLogin;$('backWelcome').onclick=()=>showScreen('welcomeScreen');$('sendOtpBtn').onclick=signIn;$('registerLink').onclick=showRegister;$('loginLink').onclick=()=>{$('registerForm').classList.add('hidden');$('loginForm').classList.remove('hidden');};$('verifyOtpBtn').onclick=verifyOtp;$('changeNumber').onclick=()=>{$('otpForm').classList.add('hidden');$('loginForm').classList.remove('hidden');};$('createAccountBtn').onclick=register;
$('themeToggle').onclick=toggleTheme;$('welcomeLanguage').onchange=e=>setLanguage(e.target.value);$('topLanguage').onchange=e=>{setLanguage(e.target.value);toast('Language preference updated. Some prototype content remains in English.');};
$('modalClose').onclick=closeModal;$('modalOverlay').onclick=e=>{if(e.target===$('modalOverlay'))closeModal();};
$('brandHome').onclick=e=>{e.preventDefault();if(state.user)renderPage('dashboard');else showScreen('welcomeScreen');};
$('logoutBtn').onclick=()=>{state.user=null;showScreen('welcomeScreen');toast('You have signed out.');};
$('switchRoleBtn').onclick=showRolePicker;$('profileBtn').onclick=()=>renderPage('profile'),$('notificationsBtn').onclick=()=>openModal(`<div class="eyebrow">UPDATES</div><h2>🔔 Smart alerts</h2><p><strong>Weather update</strong><br>Review the local forecast before outdoor work.</p><p><strong>Role-based opportunity</strong><br>New example information is available for your dashboard.</p><p><strong>Reminder</strong><br>Review today's tasks and upcoming deadlines.</p><button class="btn btn-primary btn-full" id="markRead">Mark as read</button>`);
$('assistantBtn').onclick=openAssistant;$('closeAssistant').onclick=()=>$('assistantPanel').classList.add('hidden');$('assistantForm').onsubmit=e=>{e.preventDefault();const q=$('assistantInput').value.trim();if(!q)return;appendAssistantMessage(q,assistantAnswer(q));$('assistantInput').value='';};document.querySelectorAll('[data-ask]').forEach(b=>b.onclick=()=>appendAssistantMessage(b.dataset.ask,assistantAnswer(b.dataset.ask)));
document.addEventListener('click',e=>{const page=e.target.closest('[data-page]');if(page){renderPage(page.dataset.page);return;}const action=e.target.closest('[data-action]');if(action){if(/complete your profile|edit profile|profile details/i.test(action.dataset.action)){renderPage('profile');return;}actionDetail(action.dataset.action);return;}const sch=e.target.closest('[data-scheme]');if(sch){showScheme(Number(sch.dataset.scheme));return;}const sf=e.target.closest('[data-schemefilter]');if(sf){state.schemeFilter=sf.dataset.schemefilter;renderSchemes();return;}const ct=e.target.closest('[data-croptab]');if(ct){document.querySelectorAll('[data-croptab]').forEach(x=>x.classList.toggle('active',x===ct));const tab=ct.dataset.croptab;const advice=tab==='pest'?'<div class="welcome-preview"><span class="preview-icon">🪲</span><div><strong>Inspect leaves regularly</strong><small>Look for unusual spots, wilting or pest damage. Confirm diagnosis with a local agriculture expert.</small></div></div>':tab==='irrigation'?'<div class="welcome-preview"><span class="preview-icon">💧</span><div><strong>Check soil before irrigating</strong><small>Schedule watering based on crop stage, soil and local weather.</small></div></div>':`<div class="crop-cards"><div class="crop-card"><div class="crop-emoji">🫘</div><strong>Moong bean</strong><small>Low water demand</small></div><div class="crop-card"><div class="crop-emoji">🥜</div><strong>Groundnut</strong><small>Moderate investment</small></div><div class="crop-card"><div class="crop-emoji">🌾</div><strong>Sesame</strong><small>Check local suitability</small></div></div>`;$('cropAdvice').innerHTML=advice;return;}const mf=e.target.closest('[data-marketfilter]');if(mf){state.marketFilter=mf.dataset.marketfilter;document.querySelectorAll('[data-marketfilter]').forEach(x=>x.classList.toggle('active',x===mf));const filtered=marketData.filter(m=>state.marketFilter==='All'||(state.marketFilter==='Up'?m.up:!m.up));$('marketRows').innerHTML=marketRows(filtered);return;}const fv=e.target.closest('[data-farmview]');if(fv){state.farmView=fv.dataset.farmview;renderDashboard();toast(`Field view changed to ${fv.textContent.trim()}.`);return;}const like=e.target.closest('[data-like]');if(like){let n=Number(like.textContent.match(/\d+/)?.[0]||0);like.textContent=`♥ ${n+1} Likes`;toast('Liked this demo post.');return;}const opp=e.target.closest('[data-opportunity]');if(opp){const texts=['This section can connect to verified local resources, official portals and role-specific guidance.','Review eligibility, fees, deadlines and provider information before applying.','Create a practical checklist and track your next steps here.'];openModal(`<div class="eyebrow">OPPORTUNITY</div><h2>Suggested next step</h2><p>${texts[Number(opp.dataset.opportunity)%texts.length]}</p><button class="btn btn-primary btn-full" id="oppOk">Continue</button>`);$('oppOk').onclick=closeModal;return;}if(e.target.id==='editRole'){closeModal();showRolePicker();}if(e.target.id==='markRead'){closeModal();toast('Demo notifications marked as read.');}});
document.addEventListener('click',e=>{if(e.target.id==='publishPost'){const text=$('postText').value.trim();if(!text){toast('Write something before publishing.');return;}$('feedPosts').insertAdjacentHTML('afterbegin',feedPost(escapeHtml(state.user?.name||'You'),roles[state.role].name,escapeHtml(text),'🌿',0));$('postText').value='';toast('Your demo post has been published.');}});

document.addEventListener('change',e=>{if(e.target.id==='serviceFilter')$('serviceRows').innerHTML=serviceRows(e.target.value);});
// Drag-to-pan demo map and clickable labelled pins.
let mapDrag=null;document.addEventListener('pointerdown',e=>{const map=e.target.closest('#demoMap');if(!map||e.target.closest('.map-pin'))return;mapDrag={map,x:e.clientX,y:e.clientY,left:parseFloat(map.dataset.x||'0'),top:parseFloat(map.dataset.y||'0')};map.setPointerCapture?.(e.pointerId);map.classList.add('dragging');});
document.addEventListener('pointermove',e=>{if(!mapDrag)return;const dx=e.clientX-mapDrag.x,dy=e.clientY-mapDrag.y;mapDrag.map.style.transform=`translate(${mapDrag.left+dx}px,${mapDrag.top+dy}px)`;mapDrag.map.dataset.x=mapDrag.left+dx;mapDrag.map.dataset.y=mapDrag.top+dy;});
document.addEventListener('pointerup',()=>{if(mapDrag){mapDrag.map.classList.remove('dragging');mapDrag=null;}});
document.addEventListener('click',e=>{const pin=e.target.closest('.map-pin');if(pin){$('mapPlaceInfo').textContent=pin.dataset.place;document.querySelectorAll('.map-pin').forEach(p=>p.classList.toggle('selected',p===pin));return;}if(e.target.id==='mapReset'){const map=$('demoMap');if(map){map.style.transform='translate(0px, 0px)';map.dataset.x='0';map.dataset.y='0';$('mapPlaceInfo').textContent='Map reset. Click any labelled place to see its sample details.';}return;}if(e.target.closest('[data-profile-complete]'))renderPage('profile');});
}
populateRoles();bindEvents();let savedTheme='light',savedLanguage='en';try{savedTheme=localStorage.getItem('gramsaarthi_theme')||'light';savedLanguage=localStorage.getItem('gramsaarthi_language')||'en';}catch(_){}applyTheme(savedTheme);setLanguage(savedLanguage);showScreen('welcomeScreen');
